// gen writes the files_*_gen.go files from the sibling templates folder. Run with `go generate`
// in the templates package. Files ignored by the templates' own .gitignore rules and build output
// are left out, so the embedded copy is what a fresh clone holds. Each template is written in
// parts of at most partBudget bytes of source, so no generated file reaches the repository's
// limit for a committed file.
package main

import (
	"fmt"
	"go/format"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"github.com/whisk-run/cli/templates/source"
)

// partBudget is the most source one generated file holds, well under the 2 MiB limit for a
// committed file (infra/ci/tracked_files.py). A single file larger than this gets a part of its own.
const partBudget = 1 << 20

// entry is one template file as it appears in generated source.
type entry struct {
	path string
	line string
}

// parts groups entries, in order, into runs whose lines together stay within budget. Pure.
func parts(entries []entry, budget int) [][]entry {
	var out [][]entry
	size := 0
	for _, e := range entries {
		if len(out) == 0 || (size+len(e.line) > budget && size > 0) {
			out, size = append(out, nil), 0
		}
		out[len(out)-1] = append(out[len(out)-1], e)
		size += len(e.line)
	}
	return out
}

func render(name string, part []entry) ([]byte, error) {
	var b strings.Builder
	b.WriteString("// Code generated by go generate from ../../templates; DO NOT EDIT.\n\npackage templates\n\nfunc init() {\n")
	fmt.Fprintf(&b, "\tadd(%q, map[string]File{\n", name)
	for _, e := range part {
		b.WriteString(e.line)
	}
	b.WriteString("\t})\n}\n")
	return format.Source([]byte(b.String()))
}

func fail(err error) {
	fmt.Fprintln(os.Stderr, err)
	os.Exit(1)
}

func main() {
	root := "../../templates"
	if len(os.Args) > 1 {
		root = os.Args[1]
	}
	out := map[string][]byte{}
	for _, name := range []string{"typescript", "python", "go", "shop"} {
		set, err := source.Read(filepath.Join(root, name))
		if err != nil {
			fail(err)
		}
		paths := make([]string, 0, len(set))
		for p := range set {
			paths = append(paths, p)
		}
		sort.Strings(paths)
		entries := make([]entry, 0, len(paths))
		for _, p := range paths {
			f := set[p]
			entries = append(entries, entry{p, fmt.Sprintf("\t\t%q: {Mode: %#o, Content: %q},\n", p, uint32(f.Mode), f.Content)})
		}
		for i, part := range parts(entries, partBudget) {
			src, err := render(name, part)
			if err != nil {
				fail(fmt.Errorf("generated source does not format: %w", err))
			}
			out[fmt.Sprintf("files_%s_%d_gen.go", name, i+1)] = src
		}
	}
	// Generated files from an earlier run that this one does not write would add stale files.
	old, err := filepath.Glob("files_*_gen.go")
	if err != nil {
		fail(err)
	}
	for _, f := range old {
		if _, ok := out[f]; !ok {
			if err := os.Remove(f); err != nil {
				fail(err)
			}
		}
	}
	for f, src := range out {
		if err := os.WriteFile(f, src, 0o644); err != nil {
			fail(err)
		}
	}
}
